package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.rate.RateRepository;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to (not while
     *  it is PENDING: then it is live), else
     *  live: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded to two
     *  decimals as the claim rounds (see Rounding), and at least the sheet's floor; null (n/a) when no rate applies. */
    public static BigDecimal figure(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.statedDue() != null && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, floor, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else its figure (bound or live) with
     *  the late charge on it added on top; null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        BigDecimal figure = figure(claim, grades, rates, floor, late.rounding());
        return figure != null ? figure.add(late.on(claim, figure)) : null;
    }

    /** A claim's live due: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded
     *  to two decimals as the claim rounds (see Rounding), raised to the floor when below it (a correction, a negative amount, has no floor); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .map(due -> claim.amount().signum() < 0 ? due : due.max(floor))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN or PENDING one while its person is on hold. */
    public static boolean counts(Claim claim, boolean held) {
        return claim.status().counts() && !(held && claim.status().unsettled());
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, boolean held, LocalDate today,
            RateRepository rates, BigDecimal floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, held)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's late charge as it is today: its late percent (a claim is overdue past its own due-by, fixed when
 *  it was created) and its today (null: none, so nothing is overdue). */
public record LateCharge(BigDecimal pct, LocalDate today, Rounding rounding) {

    /** The sheet's late charge as it is now. */
    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims) {
        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims));
    }

    /** No late charge at all. */
    public static LateCharge none() {
        return new LateCharge(BigDecimal.ZERO, null, Rounding.none());
    }

    /** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before today. */
    public boolean overdue(Claim claim) {
        return claim.status().unsettled() && today != null
                && claim.dueBy().isBefore(today);
    }

    /** The charge on a claim whose figure is `figure`: the late percent of the figure for every full 30 days it
     *  is overdue, rounded to two decimals as the claim rounds (see Rounding); 0.00 when it is not overdue, or it is a correction (a negative amount). */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (!overdue(claim) || pct.signum() == 0 || claim.amount().signum() < 0) {
            return new BigDecimal("0.00");
        }
        long periods = ChronoUnit.DAYS.between(claim.dueBy(), today) / 30;
        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, rounding.of(claim));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asString, useSearchParam } from '../../url/useSearchParam';
import type { Person } from '../people/people';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it
 *  PENDING until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A person's claim: the amount with two decimals, the date (yyyy-mm-dd), a note (may be empty), its status,
 *  its number (sheet-wide digits, or <period name>-<n> / X-<n> when numbered within its period; null while a draft; a voided claim keeps the one it had) and, the due fixed when it was settled
 *  (null when not settled, or its grade had no rate then: its due follows the rates), and who opened it
 *  (null while a draft), whether its person's last statement bound it (it counted then) and the figure it bound
 *  it to (null when not bound, or n/a then: its due stays live), and for a correction (a negative amount) the
 *  number of the SETTLED claim of the same person it corrects (null otherwise), and its due-by (yyyy-mm-dd), fixed
 *  when it was created from the terms of its person's grade in force on its date (else the sheet's terms). */
export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null; stated: boolean;
  statedDue: string | null; corrects: string | null; dueBy: string };

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED ones do. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether a claim is still to be settled: OPEN or PENDING (it goes overdue, and a hold takes it out of the totals). */
export function unsettled(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** The claims that count in the live totals among these: those that count, except the OPEN or PENDING claims of a person
 *  (among the people given) who is on hold; their SETTLED claims still count. */
export function live(claims: Claim[], people: Person[]): Claim[] {
  const held = new Set(people.filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => counts(c) && !(unsettled(c) && held.has(c.personId)));
}

/** A claim's due-by (yyyy-mm-dd), as fixed when it was created. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** Whether a claim is overdue: it is OPEN or PENDING and its due-by is before the sheet's today. */
export function overdue(claim: Claim, today: string): boolean {
  return unsettled(claim) && today !== '' && dueBy(claim) < today;
}

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** The id of the claim whose editor is open ('' when each person's claim form adds a new claim). */
export function useEditingClaim() {
  return useSearchParam('editClaim', asString);
}

/** The amounts of the claims that count (OPEN, PENDING and SETTLED) added up exactly (in cents) and shown
 *  with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
